/* ==========================================================================
   Estándar de interfaz v3, Gonzalo Román: tokens.css
   Variante A: Tailwind v4 + shadcn/ui actual (colores en oklch).
   La variante B (Tailwind v3, tripletas HSL) está en tokens-v3.css.

   Uso: guárdalo como src/styles/tokens.css e impórtalo en el CSS principal
   después de  @import "tailwindcss";  (y de shadcn/tailwind.css si existe),
   quitando el :root, .dark y @theme inline que trae shadcn.
   2. Neutros FIJOS. Por app solo cambian 4 variables: --primary,
      --primary-foreground, --accent y --ring. Copia el bloque del tema
      elegido dentro de :root (o deja el selector [data-tema] en <html>).
   3. Solo tema claro. No hay .dark a propósito.
   4. Base v3: blanco para trabajar, hielo para paneles, cielo en la
      barra lateral, marino como tinta. Fuente: Lexend (fonts.css).
   ========================================================================== */

/* Contraste WCAG verificado (gen_tokens.py, todo OK):
 * texto foreground sobre background                          #0F2747 / #FFFFFF  14.98  OK (mín. 4.5)
 * texto foreground sobre card                                #0F2747 / #FFFFFF  14.98  OK (mín. 4.5)
 * texto foreground sobre muted                               #0F2747 / #EEF4FA  13.53  OK (mín. 4.5)
 * texto foreground sobre sidebar                             #0F2747 / #DDEAF6  12.25  OK (mín. 4.5)
 * texto muted-foreground sobre background                    #3D5470 / #FFFFFF   7.78  OK (mín. 4.5)
 * texto muted-foreground sobre card                          #3D5470 / #FFFFFF   7.78  OK (mín. 4.5)
 * texto muted-foreground sobre muted                         #3D5470 / #EEF4FA   7.02  OK (mín. 4.5)
 * texto muted-foreground sobre sidebar                       #3D5470 / #DDEAF6   6.36  OK (mín. 4.5)
 * texto destructive sobre sidebar                            #B42318 / #DDEAF6   5.38  OK (mín. 4.5)
 * texto destructive sobre card                               #B42318 / #FFFFFF   6.57  OK (mín. 4.5)
 * texto destructive sobre background                         #B42318 / #FFFFFF   6.57  OK (mín. 4.5)
 * texto destructive-foreground sobre destructive             #FFFFFF / #B42318   6.57  OK (mín. 4.5)
 * texto success-foreground sobre success                     #FFFFFF / #2F6B3A   6.39  OK (mín. 4.5)
 * texto success sobre card                                   #2F6B3A / #FFFFFF   6.39  OK (mín. 4.5)
 * texto warning-foreground sobre warning                     #0F2747 / #D8961C   5.92  OK (mín. 4.5)
 * borde input sobre card (no textual)                        #6E8197 / #FFFFFF   4.00  OK (mín. 3.0)
 * borde input sobre background (no textual)                  #6E8197 / #FFFFFF   4.00  OK (mín. 3.0)
 * borde input sobre muted/hielo (no textual)                 #6E8197 / #EEF4FA   3.61  OK (mín. 3.0)
 * borde input sobre sidebar/cielo (no textual)               #6E8197 / #DDEAF6   3.27  OK (mín. 3.0)
 * -- tema ambar
 * [ambar] primary-foreground sobre primary                   #0F2747 / #D8961C   5.92  OK (mín. 4.5)
 * [ambar] accent-foreground sobre accent                     #0F2747 / #F6E3BC  11.87  OK (mín. 4.5)
 * [ambar] muted-foreground sobre accent (fila seleccionada)  #3D5470 / #F6E3BC   6.16  OK (mín. 4.5)
 * [ambar] ring sobre background (foco, no textual)           #8A5A0B / #FFFFFF   5.92  OK (mín. 3.0)
 * [ambar] ring sobre card (foco, no textual)                 #8A5A0B / #FFFFFF   5.92  OK (mín. 3.0)
 * [ambar] ring sobre muted (foco, no textual)                #8A5A0B / #EEF4FA   5.34  OK (mín. 3.0)
 * [ambar] ring sobre sidebar (foco, no textual)              #8A5A0B / #DDEAF6   4.84  OK (mín. 3.0)
 * -- tema oliva
 * [oliva] primary-foreground sobre primary                   #FFFFFF / #55602A   6.79  OK (mín. 4.5)
 * [oliva] accent-foreground sobre accent                     #0F2747 / #E3E7CF  11.84  OK (mín. 4.5)
 * [oliva] muted-foreground sobre accent (fila seleccionada)  #3D5470 / #E3E7CF   6.15  OK (mín. 4.5)
 * [oliva] ring sobre background (foco, no textual)           #55602A / #FFFFFF   6.79  OK (mín. 3.0)
 * [oliva] ring sobre card (foco, no textual)                 #55602A / #FFFFFF   6.79  OK (mín. 3.0)
 * [oliva] ring sobre muted (foco, no textual)                #55602A / #EEF4FA   6.13  OK (mín. 3.0)
 * [oliva] ring sobre sidebar (foco, no textual)              #55602A / #DDEAF6   5.55  OK (mín. 3.0)
 * -- tema petroleo
 * [petroleo] primary-foreground sobre primary                #FFFFFF / #1F5560   8.31  OK (mín. 4.5)
 * [petroleo] accent-foreground sobre accent                  #0F2747 / #D6E6E7  11.65  OK (mín. 4.5)
 * [petroleo] muted-foreground sobre accent (fila seleccionada) #3D5470 / #D6E6E7   6.05  OK (mín. 4.5)
 * [petroleo] ring sobre background (foco, no textual)        #1F5560 / #FFFFFF   8.31  OK (mín. 3.0)
 * [petroleo] ring sobre card (foco, no textual)              #1F5560 / #FFFFFF   8.31  OK (mín. 3.0)
 * [petroleo] ring sobre muted (foco, no textual)             #1F5560 / #EEF4FA   7.50  OK (mín. 3.0)
 * [petroleo] ring sobre sidebar (foco, no textual)           #1F5560 / #DDEAF6   6.80  OK (mín. 3.0)
 */

:root {
  --radius: 0.375rem; /* 6px: lg 6, md 4, sm 2 */
  /* Neutros fijos */
  --background: oklch(1.000 0 0); /* #FFFFFF blanco: área de trabajo */
  --foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino (tinta) */
  --card: oklch(1.000 0 0); /* #FFFFFF blanco: diálogos y tarjetas */
  --card-foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --popover: oklch(1.000 0 0); /* #FFFFFF blanco: menús y paleta */
  --popover-foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --secondary: oklch(0.964 0.010 247.9); /* #EEF4FA hielo: panel de detalle, chips */
  --secondary-foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --muted: oklch(0.964 0.010 247.9); /* #EEF4FA hielo: cabecera de tabla, skeleton */
  --muted-foreground: oklch(0.439 0.054 253.8); /* #3D5470 pizarra (secundario) */
  --accent-foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --destructive: oklch(0.500 0.182 29.5); /* #B42318 rojo */
  --destructive-foreground: oklch(1.000 0 0); /* #FFFFFF blanco */
  --success: oklch(0.475 0.100 147.7); /* #2F6B3A verde */
  --success-foreground: oklch(1.000 0 0); /* #FFFFFF blanco */
  --warning: oklch(0.720 0.145 75.8); /* #D8961C ámbar (solo relleno) */
  --warning-foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --border: oklch(0.870 0.024 250.1); /* #C9D6E4 línea fría: solo bordes necesarios */
  --input: oklch(0.596 0.040 252.3); /* #6E8197 borde de control (3:1 en blanco, hielo y cielo) */
  --sidebar: oklch(0.931 0.021 245.9); /* #DDEAF6 cielo: barra lateral */
  --sidebar-foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --sidebar-accent: oklch(1.000 0 0); /* #FFFFFF blanco: elemento activo sobre cielo */
  --sidebar-accent-foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --sidebar-border: oklch(0.870 0.024 250.1); /* #C9D6E4 línea fría */
  --chart-2: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --chart-3: oklch(0.439 0.054 253.8); /* #3D5470 pizarra */
  --chart-4: oklch(0.758 0.038 249.6); /* #9FB3C8 bruma */
  --chart-5: oklch(0.500 0.182 29.5); /* #B42318 rojo */
  /* Tema por defecto: ámbar (las 4 variables que cambian por app) */
  --primary: oklch(0.720 0.145 75.8); /* #D8961C */
  --primary-foreground: oklch(0.273 0.067 256.5); /* #0F2747 */
  --accent: oklch(0.921 0.055 85.1); /* #F6E3BC */
  --ring: oklch(0.508 0.105 71.9); /* #8A5A0B */
  /* Alias: siguen al tema automáticamente */
  --sidebar-primary: var(--primary);
  --sidebar-primary-foreground: var(--primary-foreground);
  --sidebar-ring: var(--ring);
  --chart-1: var(--primary);
}

/* Tema Oliva */
[data-tema="oliva"] {
  --primary: oklch(0.467 0.078 119.1); /* #55602A */
  --primary-foreground: oklch(1.000 0 0); /* #FFFFFF */
  --accent: oklch(0.918 0.032 114.7); /* #E3E7CF */
  --ring: oklch(0.467 0.078 119.1); /* #55602A */
}

/* Tema Petróleo */
[data-tema="petroleo"] {
  --primary: oklch(0.419 0.059 213.4); /* #1F5560 */
  --primary-foreground: oklch(1.000 0 0); /* #FFFFFF */
  --accent: oklch(0.913 0.017 201.4); /* #D6E6E7 */
  --ring: oklch(0.419 0.059 213.4); /* #1F5560 */
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-accent: var(--accent);
  --color-ring: var(--ring);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-chart-1: var(--chart-1);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: var(--radius); /* topes: nada más redondo que 6px */
  --radius-2xl: var(--radius);
  --font-sans: "Lexend", Verdana, sans-serif;
  --font-cifras: "Cifras GR", "Lexend", Verdana, sans-serif;
  /* Escala densa para Lexend: 12 / 13 / 15 / 22 */
  --text-xs: 0.75rem;   --text-xs--line-height: 1rem;
  --text-sm: 0.8125rem; --text-sm--line-height: 1.25rem;
  --text-base: 0.9375rem; --text-base--line-height: 1.375rem;
  --text-2xl: 1.375rem; --text-2xl--line-height: 1.75rem;
}

/* Base: añadir al final */
@layer base {
  html { font-family: var(--font-sans); color: var(--foreground); background: var(--background); }
  .tabular-nums { font-family: var(--font-cifras); font-variant-numeric: tabular-nums; }
}

/* Lexend (OFL), autoalojada. Estándar v3. */
@font-face{font-family:'Lexend';font-style:normal;font-weight:300 700;font-display:swap;src:url(/fonts/lexend-latin-ext.woff2) format('woff2');unicode-range:U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF}
@font-face{font-family:'Lexend';font-style:normal;font-weight:300 700;font-display:swap;src:url(/fonts/lexend-latin.woff2) format('woff2');unicode-range:U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD}
/* Cifras GR: solo 0-9 de Lexend con ancho fijo (gen_cifras.py). Se usa con tabular-nums. */
@font-face{font-family:'Cifras GR';font-style:normal;font-weight:400;font-display:swap;src:url(/fonts/cifras-gr-400.woff2) format('woff2');unicode-range:U+0030-0039}
@font-face{font-family:'Cifras GR';font-style:normal;font-weight:500;font-display:swap;src:url(/fonts/cifras-gr-500.woff2) format('woff2');unicode-range:U+0030-0039}
@font-face{font-family:'Cifras GR';font-style:normal;font-weight:600;font-display:swap;src:url(/fonts/cifras-gr-600.woff2) format('woff2');unicode-range:U+0030-0039}
